body {
    /* Optimizes font rendering for crispness and clarity across browsers */
    -webkit-font-smoothing: antialiased; /* Enhances rendering on WebKit-based browsers (e.g., Chrome/Safari on macOS) */
    -moz-osx-font-smoothing: grayscale; /* Aims for a similar high-contrast effect on Firefox (macOS) */
    text-rendering: optimizeLegibility; /* Prioritizes legibility, kerning, and ligatures over rendering speed */
}

/* For critical UI elements like headings or hero text, reinforce these settings */
h1, .hero-title {
    text-rendering: optimizeLegibility;
    /* Consider setting font-weight and line-height carefully for optimal sharpness */
}
